<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import {
  shortDramaApi, type AdaptationCandidate, type DramaEpisode, type DramaScene,
  type AIProvider, type CreativeJob, type NovelAnalysis, type Screenplay, type ScreenplayRevisionCandidate, type SourceContent, type StoryVersion, type WorldOverview,
} from '@/api/modules'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'

const route = useRoute(); const router = useRouter()
const projectId = computed(() => Number(route.params.id))
const screenplay = ref<Screenplay|null>(null)
const documents = ref<any[]>([]); const versions = ref<StoryVersion[]>([])
const world = ref<WorldOverview>({characters:[],locations:[],props:[],relationships:[]})
const loading = ref(true); const error = ref(''); const notice = ref('')
const planning = ref(false); const candidate = ref<AdaptationCandidate|null>(null); const selectedOption = ref('balanced')
const documentId = ref<number|null>(null); const chapterStart = ref(1); const chapterEnd = ref(1); const episodeCount = ref(1)
const selectedEpisodeId = ref<number|null>(null); const selectedSceneId = ref<number|null>(null)
const sceneDraft = ref<DramaScene|null>(null); const sourcePreview = ref<SourceContent|null>(null)
const compareVersion = ref<StoryVersion|null>(null)
const providers=ref<AIProvider[]>([]);const analyses=ref<NovelAnalysis[]>([]);const aiJob=ref<CreativeJob|null>(null);const aiWorking=ref(false)
const episodeInstruction=ref('');const episodeCandidates=ref<ScreenplayRevisionCandidate[]>([]);const episodeAIWorking=ref(false)
const dragged = ref<{type:'episode'|'scene';id:number;episodeId?:number}|null>(null)
const mobileTab = ref<'structure'|'editor'|'context'>('editor')
const saving = ref(false); const dirty = ref(false); let suppress = false; let saveTimer: ReturnType<typeof setTimeout>|null = null;let aiTimer:ReturnType<typeof setInterval>|null=null

const episodes = computed(() => screenplay.value?.episodes || [])
const selectedEpisode = computed(() => episodes.value.find(item=>item.id===selectedEpisodeId.value)||null)
const selectedScene = computed(() => selectedEpisode.value?.scenes.find(item=>item.id===selectedSceneId.value)||null)
const chosenOption = computed(() => candidate.value?.options.find(item=>item.key===selectedOption.value)||null)

function selectInitial() {
  const episode = episodes.value.find(item=>item.id===selectedEpisodeId.value) || episodes.value[0]
  selectedEpisodeId.value = episode?.id || null
  const scene = episode?.scenes.find(item=>item.id===selectedSceneId.value) || episode?.scenes[0]
  selectedSceneId.value = scene?.id || null
}
async function load() {
  loading.value=true;error.value=''
  try {
    const [screenplayData, documentData, versionData, worldData,providerData,analysisData] = await Promise.all([
      shortDramaApi.screenplay(projectId.value), shortDramaApi.documents(projectId.value), shortDramaApi.versions(projectId.value), shortDramaApi.world(projectId.value),shortDramaApi.aiProviders(),shortDramaApi.novelAnalyses(projectId.value),
    ])
    screenplay.value=screenplayData;documents.value=documentData.filter(item=>item.status==='ready');versions.value=versionData.items;world.value=worldData;providers.value=providerData;analyses.value=analysisData
    if(!documentId.value&&documents.value.length){documentId.value=documents.value[0].id;chapterEnd.value=documents.value[0].total_chapters;episodeCount.value=Math.min(screenplayData.project.settings?.episode_count as number||8,documents.value[0].total_chapters)}
    planning.value=!screenplayData.episodes.length;selectInitial()
  }catch(event:any){error.value=event.response?.data?.detail||'剧本工作台加载失败'}finally{loading.value=false}
}
function chooseDocument(){const doc=documents.value.find(item=>item.id===documentId.value);if(doc){chapterStart.value=1;chapterEnd.value=doc.total_chapters;episodeCount.value=Math.min(8,doc.total_chapters)}}
async function generateCandidate(){if(!documentId.value)return;error.value='';notice.value='正在生成可确认的编排候选…'
  try{candidate.value=await shortDramaApi.createCandidate(projectId.value,{document_id:documentId.value,chapter_start:chapterStart.value,chapter_end:chapterEnd.value,episode_count:episodeCount.value});selectedOption.value='balanced';notice.value='候选已生成，当前剧本尚未改变。'}
  catch(event:any){error.value=event.response?.data?.detail||'候选生成失败';notice.value=''}
}
async function refreshAI(){const [analysisData,jobs]=await Promise.all([shortDramaApi.novelAnalyses(projectId.value),shortDramaApi.jobs({project_id:projectId.value,page_size:20})]);analyses.value=analysisData;const latest=jobs.items.find(item=>['analyze_novel','generate_adaptation','generate_episode_screenplay'].includes(item.job_type));if(latest)aiJob.value=latest;if(latest?.status==='succeeded'&&latest.job_type==='generate_adaptation'&&!candidate.value){const candidates=await shortDramaApi.candidates(projectId.value);candidate.value=candidates[0]||null;if(candidate.value)selectedOption.value=candidate.value.options[0]?.key||'faithful'}if(latest?.job_type==='generate_episode_screenplay'){episodeAIWorking.value=['queued','running','cancelling'].includes(latest.status);if(latest.status==='succeeded'&&Number(latest.output_payload.episode_id)===selectedEpisodeId.value)await loadEpisodeCandidates()}aiWorking.value=!!latest&&['queued','running','cancelling'].includes(latest.status)}
async function analyzeWithAI(){if(!documentId.value||!providers.value.length)return;error.value='';notice.value='小说分析任务已提交，页面可以继续操作。';try{aiJob.value=await shortDramaApi.analyzeNovel(projectId.value,{document_id:documentId.value,chapter_start:chapterStart.value,chapter_end:chapterEnd.value,idempotency_key:crypto.randomUUID()});aiWorking.value=true}catch(event:any){error.value=event.response?.data?.detail||'AI 分析任务创建失败'}}
async function confirmAnalysis(item:NovelAnalysis){try{await shortDramaApi.confirmNovelAnalysis(projectId.value,item.id);notice.value='故事档案已确认';await refreshAI()}catch(event:any){error.value=event.response?.data?.detail||'故事档案确认失败'}}
async function generateWithAI(item:NovelAnalysis){error.value='';try{if(item.status!=='confirmed')await shortDramaApi.confirmNovelAnalysis(projectId.value,item.id);aiJob.value=await shortDramaApi.generateAIAdaptation(projectId.value,{analysis_id:item.id,episode_count:episodeCount.value,strategies:['faithful','high_tempo','emotional'],idempotency_key:crypto.randomUUID()});aiWorking.value=true;notice.value='AI 正在生成可比较的改编方案。'}catch(event:any){error.value=event.response?.data?.detail||'AI 改编任务创建失败'}}
async function confirmCandidate(){if(!candidate.value||!chosenOption.value)return;if(episodes.value.length&&!window.confirm('确认后会用该方案替换当前人工草稿，并创建一个新版本。继续吗？'))return
  try{await shortDramaApi.confirmCandidate(projectId.value,candidate.value.id,{option_key:selectedOption.value,version_name:`${chosenOption.value.label}首版`});candidate.value=null;planning.value=false;notice.value='方案已确认并保存为新版本';await load()}
  catch(event:any){error.value=event.response?.data?.detail||'确认方案失败'}
}
function editScene(scene:DramaScene){selectedSceneId.value=scene.id;selectedEpisodeId.value=scene.episode_id;mobileTab.value='editor'}
async function loadSource(scene:DramaScene|null){sourcePreview.value=null;const ref=scene?.source_references?.[0];if(!ref)return
  try{sourcePreview.value=await shortDramaApi.sourceContent(projectId.value,ref.document_id,{chapter_start:ref.chapter_number,chapter_end:ref.chapter_number})}catch{/* 引用失效由保存校验提示 */}}
watch(selectedScene,async(scene)=>{suppress=true;sceneDraft.value=scene?structuredClone(scene):null;dirty.value=false;await nextTick();suppress=false;void loadSource(scene)},{immediate:true})
watch(sceneDraft,()=>{if(suppress||!sceneDraft.value)return;dirty.value=true;if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>void saveScene(),900)},{deep:true})
async function saveScene(){if(!sceneDraft.value||saving.value||!dirty.value)return;if(saveTimer){clearTimeout(saveTimer);saveTimer=null}saving.value=true
  const draft=sceneDraft.value
  try{const updated=await shortDramaApi.patchScene(projectId.value,draft.id,{lock_version:draft.lock_version,heading:draft.heading,location_name:draft.location_name,time_of_day:draft.time_of_day,interior_exterior:draft.interior_exterior,content:draft.content,elements:draft.elements,source_references:draft.source_references,character_ids:draft.character_ids,location_id:draft.location_id,purpose:draft.purpose,target_duration:draft.target_duration});const episode=episodes.value.find(item=>item.id===updated.episode_id);if(episode){const index=episode.scenes.findIndex(item=>item.id===updated.id);episode.scenes[index]=updated}suppress=true;sceneDraft.value=structuredClone(updated);dirty.value=false;notice.value='人工草稿已自动保存';await nextTick();suppress=false}
  catch(event:any){error.value=event.response?.status===409?'场景已在其他页面修改，请刷新后继续':event.response?.data?.detail||'场景保存失败'}finally{saving.value=false}}
function addElement(){sceneDraft.value?.elements.push({type:'action',text:''})}
function removeElement(index:number){sceneDraft.value?.elements.splice(index,1)}
async function addEpisode(){const item=await shortDramaApi.createEpisode(projectId.value,{title:`第 ${episodes.value.length+1} 集`,target_duration:60});await load();selectedEpisodeId.value=item.id;selectedSceneId.value=null}
async function renameEpisode(episode:DramaEpisode){const title=window.prompt('分集名称',episode.title);if(!title)return;await shortDramaApi.patchEpisode(projectId.value,episode.id,{lock_version:episode.lock_version,title});await load()}
async function removeEpisode(episode:DramaEpisode){if(!window.confirm(`删除“${episode.title}”及其全部场景？`))return;await shortDramaApi.deleteEpisode(projectId.value,episode.id);selectedEpisodeId.value=null;selectedSceneId.value=null;await load()}
async function addScene(episode:DramaEpisode){const item=await shortDramaApi.createScene(projectId.value,episode.id,{heading:'新场景',elements:[{type:'action',text:'请填写场景动作。'}]});await load();editScene(item)}
async function copyScene(scene:DramaScene){const item=await shortDramaApi.createScene(projectId.value,scene.episode_id,{heading:`${scene.heading}（副本）`,location_name:scene.location_name,time_of_day:scene.time_of_day,interior_exterior:scene.interior_exterior,content:scene.content,elements:scene.elements,source_references:scene.source_references,character_ids:scene.character_ids,location_id:scene.location_id,purpose:scene.purpose,target_duration:scene.target_duration});await load();editScene(item)}
async function removeScene(scene:DramaScene){if(!window.confirm(`删除场景“${scene.heading}”？`))return;await shortDramaApi.deleteScene(projectId.value,scene.id);selectedSceneId.value=null;await load()}
async function moveEpisode(index:number,delta:number){const ids=episodes.value.map(item=>item.id);const target=index+delta;if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]];screenplay.value=await shortDramaApi.reorderScreenplay(projectId.value,{episode_ids:ids,scene_ids_by_episode:{}})}
function startEpisodeDrag(id:number){dragged.value={type:'episode',id}}
async function dropEpisode(targetId:number){if(dragged.value?.type!=='episode'||dragged.value.id===targetId)return;const ids=episodes.value.map(item=>item.id);const from=ids.indexOf(dragged.value.id),to=ids.indexOf(targetId);ids.splice(to,0,ids.splice(from,1)[0]);screenplay.value=await shortDramaApi.reorderScreenplay(projectId.value,{episode_ids:ids,scene_ids_by_episode:{}});dragged.value=null}
function startSceneDrag(scene:DramaScene){dragged.value={type:'scene',id:scene.id,episodeId:scene.episode_id}}
async function dropScene(target:DramaScene){if(dragged.value?.type!=='scene'||dragged.value.episodeId!==target.episode_id||dragged.value.id===target.id)return;const episode=episodes.value.find(item=>item.id===target.episode_id);if(!episode)return;const ids=episode.scenes.map(item=>item.id);const from=ids.indexOf(dragged.value.id),to=ids.indexOf(target.id);ids.splice(to,0,ids.splice(from,1)[0]);screenplay.value=await shortDramaApi.reorderScreenplay(projectId.value,{episode_ids:episodes.value.map(item=>item.id),scene_ids_by_episode:{[episode.id]:ids}});dragged.value=null}
function versionStats(version:StoryVersion){const eps=Array.isArray(version.content.episodes)?version.content.episodes:[];return{episodes:eps.length,scenes:eps.reduce((sum:number,item:any)=>sum+(Array.isArray(item.scenes)?item.scenes.length:0),0)}}
async function saveVersion(){if(dirty.value)await saveScene();const name=window.prompt('版本名称',`人工版本 ${versions.value.length+1}`);if(!name)return;await shortDramaApi.createVersion(projectId.value,name);notice.value='人工草稿已保存为新版本';await load()}
async function restoreVersion(version:StoryVersion){if(!window.confirm(`恢复 V${version.version}“${version.name}”并另存为新版本？`))return;await shortDramaApi.restoreVersion(projectId.value,version.id);notice.value='旧版本已恢复为新的当前版本';await load()}
async function loadEpisodeCandidates(){episodeCandidates.value=selectedEpisodeId.value?await shortDramaApi.episodeScreenplayCandidates(projectId.value,selectedEpisodeId.value):[]}
watch(selectedEpisodeId,()=>{episodeCandidates.value=[];void loadEpisodeCandidates()})
async function generateEpisodeAI(){const episode=selectedEpisode.value;if(!episode)return;if(dirty.value)await saveScene();error.value='';try{aiJob.value=await shortDramaApi.generateEpisodeScreenplay(projectId.value,episode.id,{provider_config_id:providers.value[0]?.id,instruction:episodeInstruction.value,idempotency_key:crypto.randomUUID()});episodeAIWorking.value=true;aiWorking.value=true;notice.value=`第 ${episode.number} 集 AI 剧本任务已提交，完成后先生成候选，不会覆盖当前草稿。`}catch(event:any){error.value=event.response?.data?.detail||'单集 AI 剧本任务创建失败'}}
async function applyEpisodeCandidate(item:ScreenplayRevisionCandidate){const episode=selectedEpisode.value;if(!episode||!window.confirm('应用后将替换本集场景并自动创建一个历史版本，继续吗？'))return;try{await shortDramaApi.confirmEpisodeScreenplayCandidate(projectId.value,episode.id,item.id);notice.value='AI 单集剧本已应用，并保存为新版本';await load();await loadEpisodeCandidates()}catch(event:any){error.value=event.response?.data?.detail||'应用候选失败'}}
async function toggleEpisodeLock(){const episode=selectedEpisode.value;if(!episode)return;try{await shortDramaApi.patchEpisode(projectId.value,episode.id,{lock_version:episode.lock_version,is_locked:!episode.is_locked});notice.value=episode.is_locked?'分集已解锁':'分集已锁定，AI 不会覆盖该集';await load()}catch(event:any){error.value=event.response?.data?.detail||'修改锁定状态失败'}}
onBeforeRouteLeave(()=>dirty.value?window.confirm('场景修改尚未保存，确定离开吗？'):true)
onMounted(()=>{void load().then(refreshAI);aiTimer=setInterval(()=>{if(aiWorking.value)void refreshAI()},2500)});onBeforeUnmount(()=>{if(saveTimer)clearTimeout(saveTimer);if(aiTimer)clearInterval(aiTimer)})
</script>

<template>
  <div class="v2-page screenplay-page">
    <div v-if="loading" class="loading">正在加载剧本工作台…</div>
    <template v-else-if="screenplay">
      <header class="page-head"><div><button class="back" @click="router.push(`/v2/drama/projects/${projectId}`)">← 项目概览</button><h1>{{ screenplay.project.name }}</h1><p>剧本工作台 · 人工草稿与历史版本分离保存</p></div><div class="head-actions"><StatusBadge :tone="screenplay.draft_changed||dirty?'warning':'success'">{{ screenplay.draft_changed||dirty?'草稿有修改':'已形成版本' }}</StatusBadge><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/world`)">角色与世界设定</V2Button><V2Button variant="ghost" @click="planning=!planning">{{ planning?'返回编辑':'重新编排' }}</V2Button><V2Button variant="primary" @click="saveVersion">保存新版本</V2Button></div></header>
      <p v-if="error" class="banner error">{{ error }}</p><p v-if="notice" class="banner notice">{{ notice }}</p>

      <section v-if="planning" class="planning-panel">
        <div class="ai-head"><div><StatusBadge :tone="providers.length?'success':'warning'">{{ providers.length?'真实 AI 已配置':'尚未配置 AI' }}</StatusBadge><h2>小说 AI 改编</h2><p>先分块分析人物、事件和时间线，确认故事档案后再生成改编方案。不会一次发送整本小说。</p></div><V2Button variant="primary" :disabled="!documentId||!providers.length||aiWorking" @click="analyzeWithAI">{{ aiWorking?'AI 处理中…':'① AI 分析小说' }}</V2Button></div>
        <div class="planning-form"><label>源文档<select v-model="documentId" @change="chooseDocument"><option v-for="doc in documents" :key="doc.id" :value="doc.id">{{ doc.title }}（{{ doc.total_chapters }} 章）</option></select></label><label>起始章节<input v-model.number="chapterStart" type="number" min="1" :max="chapterEnd"></label><label>结束章节<input v-model.number="chapterEnd" type="number" :min="chapterStart"></label><label>目标集数<input v-model.number="episodeCount" type="number" min="1" max="100"></label><V2Button variant="ghost" :disabled="!documentId" @click="generateCandidate">使用本地规则</V2Button></div>
        <article v-if="aiJob" class="ai-progress"><div><b>{{ aiJob.job_type==='analyze_novel'?'小说分析':'改编方案生成' }}</b><span>{{ aiJob.status }} · {{ aiJob.progress }}%</span></div><progress :value="aiJob.progress" max="100"></progress><p v-if="aiJob.error">{{ aiJob.error }}</p><small v-if="aiJob.token_usage?.total_tokens">Token：{{ aiJob.token_usage.total_tokens }} · 模型：{{ aiJob.model }}</small></article>
        <div v-if="analyses.length" class="analysis-grid"><article v-for="item in analyses" :key="item.id" :class="{confirmed:item.status==='confirmed'}"><header><b>故事档案 V{{ item.version }}</b><StatusBadge :tone="item.status==='confirmed'?'success':item.validation_errors.length?'warning':'neutral'">{{ item.status==='confirmed'?'已确认':item.validation_errors.length?'有建议':'候选' }}</StatusBadge></header><p>{{ item.content.synopsis||'暂无故事梗概' }}</p><small>{{ item.content.characters?.length||0 }} 人物 · {{ item.content.events?.length||0 }} 事件 · 第 {{ item.chapter_start }}–{{ item.chapter_end }} 章；检查结果不限制后续操作。</small><footer><V2Button v-if="item.status!=='confirmed'" variant="ghost" @click="confirmAnalysis(item)">确认档案</V2Button><V2Button variant="primary" :disabled="aiWorking" @click="generateWithAI(item)">② 生成 AI 改编方案</V2Button></footer></article></div>
        <div v-if="!documents.length" class="empty">请先在“文档导入”完成原稿解析。</div>
        <div v-if="candidate" class="option-grid"><button v-for="option in candidate.options" :key="option.key" :class="{selected:selectedOption===option.key}" @click="selectedOption=option.key"><span class="radio"></span><strong>{{ option.label }}</strong><p>{{ option.description }}</p><small>{{ option.metrics.episode_count }} 集 · {{ option.metrics.source_chapters }} 章 · 节奏 {{ option.metrics.pace_ratio }}</small></button></div>
        <div v-if="candidate" class="candidate-foot"><span>选择方案只进行预览，点击确认后才会写入剧本并生成新版本。</span><V2Button variant="primary" @click="confirmCandidate">确认 {{ chosenOption?.label }}</V2Button></div>
      </section>

      <div v-else class="mobile-tabs"><button :class="{active:mobileTab==='structure'}" @click="mobileTab='structure'">结构</button><button :class="{active:mobileTab==='editor'}" @click="mobileTab='editor'">编辑</button><button :class="{active:mobileTab==='context'}" @click="mobileTab='context'">原文与版本</button></div>
      <main v-if="!planning" class="workspace">
        <aside class="structure-pane" :class="{mobileHidden:mobileTab!=='structure'}"><div class="pane-title"><div><strong>分集与场景</strong><small>{{ episodes.length }} 集 · 支持拖动排序</small></div><button @click="addEpisode">＋ 分集</button></div><div v-if="!episodes.length" class="empty">还没有剧本结构，请先生成候选或手工添加。</div><section v-for="(episode,index) in episodes" :key="episode.id" class="episode" :class="{active:selectedEpisodeId===episode.id}"><header draggable="true" @dragstart="startEpisodeDrag(episode.id)" @dragover.prevent @drop.prevent="dropEpisode(episode.id)" @click="selectedEpisodeId=episode.id"><span>EP {{ episode.number }}</span><strong>{{ episode.title }}</strong><div class="mini"><button title="上移" @click.stop="moveEpisode(index,-1)">↑</button><button title="下移" @click.stop="moveEpisode(index,1)">↓</button><button title="改名" @click.stop="renameEpisode(episode)">✎</button><button title="删除" @click.stop="removeEpisode(episode)">×</button></div></header><button v-for="scene in episode.scenes" :key="scene.id" draggable="true" class="scene-link" :class="{active:selectedSceneId===scene.id}" @dragstart="startSceneDrag(scene)" @dragover.prevent @drop.prevent="dropScene(scene)" @click="editScene(scene)"><span>{{ scene.scene_no }}</span><b>{{ scene.heading }}</b><i title="复制" @click.stop="copyScene(scene)">⧉</i><i title="删除" @click.stop="removeScene(scene)">×</i></button><button class="add-scene" @click="addScene(episode)">＋ 添加场景</button></section></aside>

        <section class="editor-pane" :class="{mobileHidden:mobileTab!=='editor'}">
          <article v-if="selectedEpisode" class="episode-ai-box">
            <header><div><small>EP {{ selectedEpisode.number }} · 单集 AI 编剧</small><strong>{{ selectedEpisode.title }}</strong></div><button :class="{locked:selectedEpisode.is_locked}" @click="toggleEpisodeLock">{{ selectedEpisode.is_locked?'🔒 已锁定':'🔓 锁定本集' }}</button></header>
            <div class="episode-plan"><span><b>冲突</b>{{ selectedEpisode.core_conflict||'待补充' }}</span><span><b>情绪</b>{{ selectedEpisode.emotional_arc||'待补充' }}</span><span><b>开场钩子</b>{{ selectedEpisode.opening_hook||'待补充' }}</span><span><b>结尾钩子</b>{{ selectedEpisode.ending_hook||'待补充' }}</span></div>
            <div class="episode-ai-action"><input v-model="episodeInstruction" placeholder="可选：例如加强男女主冲突、减少复杂场景"><V2Button variant="primary" :disabled="selectedEpisode.is_locked||!providers.length||episodeAIWorking" @click="generateEpisodeAI">{{ episodeAIWorking?'AI 编写中…':'AI 生成本集剧本' }}</V2Button></div>
            <div v-if="!providers.length" class="ai-hint">请先在“系统配置 → AI 模型配置”添加模型。</div>
            <article v-if="episodeCandidates[0]" class="episode-candidate">
              <div><StatusBadge :tone="episodeCandidates[0].status==='confirmed'?'success':'warning'">{{ episodeCandidates[0].status==='confirmed'?'已应用':episodeCandidates[0].validation_errors.length?'有建议':'待确认' }}</StatusBadge><b>{{ episodeCandidates[0].content.title||'AI 单集候选' }}</b><span>{{ episodeCandidates[0].content.scenes?.length||0 }} 场 · {{ episodeCandidates[0].content.target_duration||0 }} 秒</span></div>
              <p>{{ episodeCandidates[0].content.synopsis }}</p>
              <ol><li v-for="(scene,index) in episodeCandidates[0].content.scenes||[]" :key="index">{{ scene.heading }} · {{ scene.target_duration||0 }} 秒</li></ol>
              <V2Button v-if="episodeCandidates[0].status==='pending'" variant="primary" @click="applyEpisodeCandidate(episodeCandidates[0])">预览确认并应用</V2Button>
            </article>
          </article>
          <div v-if="!sceneDraft" class="empty full">从左侧选择场景，或新建一个场景。</div><template v-else><div class="editor-head"><div><small>场景 {{ sceneDraft.scene_no }}</small><input v-model="sceneDraft.heading" aria-label="场景标题"></div><span>{{ saving?'保存中…':dirty?'等待自动保存':'草稿已保存' }}</span></div><div class="meta-grid"><label>地点名称<input v-model="sceneDraft.location_name" placeholder="场景地点"></label><label>时间<input v-model="sceneDraft.time_of_day" placeholder="日 / 夜"></label><label>内外景<select v-model="sceneDraft.interior_exterior"><option value="">未设置</option><option value="INT">内景</option><option value="EXT">外景</option></select></label><label>预计秒数<input v-model.number="sceneDraft.target_duration" type="number" min="0"></label></div><div class="setting-links"><label>关联地点<select v-model="sceneDraft.location_id"><option :value="null">不关联地点卡</option><option v-for="item in world.locations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><fieldset><legend>出场角色</legend><label v-for="item in world.characters" :key="item.id"><input v-model="sceneDraft.character_ids" type="checkbox" :value="item.id">{{ item.name }}</label><span v-if="!world.characters.length">请先在角色与世界设定中确认角色</span></fieldset></div><label class="field"><span>场景正文</span><textarea v-model="sceneDraft.content" rows="10"></textarea></label><div class="elements-head"><div><strong>剧本元素</strong><small>动作、对白、旁白与转场采用结构化语义</small></div><button @click="addElement">＋ 元素</button></div><article v-for="(element,index) in sceneDraft.elements" :key="index" class="element-row"><select v-model="element.type"><option value="action">动作</option><option value="dialogue">对白</option><option value="narration">旁白</option><option value="transition">转场</option></select><input v-if="element.type==='dialogue'" v-model="element.speaker" placeholder="说话人"><textarea v-model="element.text" rows="2" placeholder="元素内容"></textarea><button @click="removeElement(index)">×</button></article></template>
        </section>

        <aside class="context-pane" :class="{mobileHidden:mobileTab!=='context'}"><section><div class="pane-title"><div><strong>原文定位</strong><small>场景引用来源</small></div></div><div v-if="!sourcePreview" class="empty compact">当前场景没有原文引用。</div><template v-else><article v-for="chapter in sourcePreview.chapters" :key="chapter.id" class="source-chapter"><b>第 {{ chapter.number }} 章 · {{ chapter.title||'未命名' }}</b><p v-for="paragraph in chapter.paragraphs" :key="paragraph.id">{{ paragraph.text }}</p></article></template></section><section class="versions"><div class="pane-title"><div><strong>版本记录</strong><small>{{ versions.length }} 个不可变快照</small></div></div><div v-if="compareVersion" class="compare-box"><b>与当前版本比较</b><p>V{{ compareVersion.version }}：{{ versionStats(compareVersion).episodes }} 集 / {{ versionStats(compareVersion).scenes }} 场</p><p>当前：{{ episodes.length }} 集 / {{ episodes.reduce((sum,item)=>sum+item.scenes.length,0) }} 场</p><button @click="compareVersion=null">关闭比较</button></div><article v-for="version in versions" :key="version.id" :class="{current:version.is_current}"><div><b>V{{ version.version }} · {{ version.name }}</b><small>{{ version.source }} · {{ new Date(version.created_at).toLocaleString() }}</small></div><StatusBadge v-if="version.is_current" tone="success">当前</StatusBadge><template v-else><button @click="compareVersion=version">比较</button><button @click="restoreVersion(version)">恢复</button></template></article></section></aside>
      </main>
    </template>
  </div>
</template>

